const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { es_mensaje: false } }];
}

return [{
  json: {
    es_mensaje: true,
    from: message.from,
    texto: message.text?.body || '',
    message_id: message.id,
    timestamp: message.timestamp,
    nombre_contacto: value.contacts?.[0]?.profile?.name || ''
  }
}];

// El listado de marcas ya no se inyecta en el prompt: son 846 y multiplicaba
// el costo de tokens en cada mensaje. La marca se resuelve por SQL despues.
const datos = $('Extraer Datos Mensaje').item.json;
return [{ json: { mensaje_cliente: datos.texto, numero_from: datos.from } }];

let resultado;
try {
  // Gemini devuelve el texto en candidates[0].content.parts[0].text
  const r = $input.first().json;
  const texto = r.candidates?.[0]?.content?.parts?.[0]?.text
             ?? r.content?.[0]?.text;   // compatibilidad si se vuelve a Anthropic
  resultado = JSON.parse(texto);
} catch (e) {
  resultado = {
    intencion: 'otro',
    termino_busqueda: null,
    codigo_detectado: null,
    marca_mencionada: null,
    cantidad_solicitada: null,
    requiere_humano: true,
    motivo_derivacion: 'Error de clasificacion (respuesta no parseable)',
    confianza: 'baja'
  };
}

return [{
  json: {
    ...resultado,
    numero_from: $('Preparar Prompt').item.json.numero_from,
    mensaje_original: $('Preparar Prompt').item.json.mensaje_cliente
  }
}];

const filas = $input.all().map(i => i.json);

if (filas.length === 0) {
  return [{ json: {
    respuesta: 'No encontre ese producto en el catalogo. Te derivo con un asesor para confirmarlo.',
    sin_resultados: true
  } }];
}

// Si el producto no tiene precio cargado, no mostrar '$null'
const money = v => (v === null || v === undefined)
  ? 'precio a confirmar'
  : '$' + Number(v).toLocaleString('es-AR', { minimumFractionDigits: 2 });

const disponibles = filas.filter(p => p.estado === 'DISPONIBLE');
const agotados    = filas.filter(p => p.estado === 'SIN_STOCK');

const partes = [];
if (disponibles.length) {
  const items = disponibles
    .map(p => `- ${p.nombre} | ${p.stock} u. | ${money(p.precio)}`)
    .join('\n');
  partes.push('Disponible:\n' + items);
}
if (agotados.length) {
  const items = agotados
    .map(p => `- ${p.nombre}`)
    .join('\n');
  partes.push('Sin stock por el momento:\n' + items);
}

// Una sola respuesta consolidada: cada mensaje saliente se factura aparte.
return [{ json: {
  respuesta: partes.join('\n\n'),
  sin_resultados: false,
  hay_disponibles: disponibles.length > 0
} }];

const filas = $input.all();
const datosClasificacion = $('Parsear JSON IA').first().json;

// Fallback: si no hay comprador asignado por marca, usar admin general
const comprador = filas.length > 0
  ? filas[0].json
  : { nombre: 'Administración General', numero_whatsapp: 'CAMBIAR_NUMERO_ADMIN_FALLBACK' };

return [{
  json: {
    comprador_nombre: comprador.nombre,
    comprador_numero: comprador.numero_whatsapp,
    farmacia_numero: datosClasificacion.numero_from,
    mensaje_original: datosClasificacion.mensaje_original,
    motivo: datosClasificacion.motivo_derivacion || 'Consulta general'
  }
}];

